import * as React from "react";
import { useEffect } from "react";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import type {
  I18nPageContext,
  LocaleQueryData,
} from "./I18nHeadProvider";
import I18nHeadProvider from "./I18nHeadProvider";
import Layout from "./Layout";
import Link from "./AppLink";
import SEO from "./seo";
import CaseStudyProofGrid, {
  type CaseStudyProofItem,
  type CaseStudyProofLabels,
} from "./CaseStudyProofGrid";
import data from "../data/data.json";
import images from "../images";
import type { Company } from "../interfaces";
import { buildContactIntentPath } from "../utils/cta";
import { getCaseStudyProofSource } from "../utils/caseStudyProof";
import { getServicePathFromKey } from "../utils/journeyLinks";
import {
  getProblemLandingConfig,
  type ProblemLandingKey,
} from "../utils/problemLandings";
import {
  buildBreadcrumbListSchema,
  localizeSitePath,
} from "../utils/structuredData";

const info: Company = data[0];

type BulletItem = {
  item: string;
};

type Props = {
  landingKey: ProblemLandingKey;
};

const cardClassName =
  "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light";

const normalizeBulletItems = (input: unknown): BulletItem[] =>
  Array.isArray(input)
    ? input.filter(
        (item): item is BulletItem =>
          Boolean(
            item &&
              typeof item === "object" &&
              "item" in item &&
              typeof item.item === "string" &&
              item.item.trim()
          )
      )
    : [];

const normalizeStringItems = (input: unknown): string[] =>
  Array.isArray(input)
    ? input
        .map((item) => (typeof item === "string" ? item.trim() : ""))
        .filter(Boolean)
    : [];

export const ProblemLandingPage: React.FC<Props> = ({ landingKey }) => {
  const { t } = useTranslation(["problem-landings", "index"]);
  const config = getProblemLandingConfig(landingKey);
  const root = config.translationRoot;
  const primaryServicePath = getServicePathFromKey(config.primaryServiceKey);
  const primaryIntentPath = buildContactIntentPath(config.contactIntent);

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const heroChips = normalizeStringItems(
    t(`${root}.hero.chips`, {
      returnObjects: true,
      defaultValue: [],
    }) as unknown
  );
  const whenFitItems = normalizeBulletItems(
    t(`${root}.whenFit.items`, {
      returnObjects: true,
      defaultValue: [],
    }) as unknown
  );
  const commonMistakesItems = normalizeBulletItems(
    t(`${root}.commonMistakes.items`, {
      returnObjects: true,
      defaultValue: [],
    }) as unknown
  );
  const nextStepItems = normalizeBulletItems(
    t(`${root}.nextStep.items`, {
      returnObjects: true,
      defaultValue: [],
    }) as unknown
  );
  const proofLabels = t("proofBlocks.labels", {
    ns: "index",
    returnObjects: true,
  }) as CaseStudyProofLabels;
  const proofCtaLabel = t("proofBlocks.ctaLabel", {
    ns: "index",
  }) as string;
  const proofSource = getCaseStudyProofSource(t, config.proofSlug);
  const proofItems: CaseStudyProofItem[] = [
    {
      client: proofSource.client,
      businessType: proofSource.businessType,
      problem: proofSource.challenges[0] || "",
      intervention:
        proofSource.interventions[0] ||
        proofSource.interventions[1] ||
        "",
      result:
        proofSource.results[0] ||
        proofSource.metrics[0]?.value ||
        "",
      href: proofSource.href,
      ctaLabel: proofCtaLabel,
    },
  ].filter(
    (item) =>
      item.client &&
      item.businessType &&
      item.problem &&
      item.intervention &&
      item.result
  );

  return (
    <Layout data={info}>
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className="mx-auto w-full max-w-6xl px-4 sm:px-6">
          <div className="mx-auto max-w-5xl text-center">
            <p className="uppercase tracking-[0.2em] text-xs text-verde">
              {t(`${root}.hero.kicker`)}
            </p>
            <h1 className="mt-3 text-3xl sm:text-5xl poppins-bold text-light">
              {t(`${root}.hero.title`)}
            </h1>
            <p className="mt-4 text-lg sm:text-xl text-light/85">
              {t(`${root}.hero.subtitle`)}
            </p>

            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to={primaryIntentPath}
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t(`${root}.hero.primaryCta`)}
              </Link>
              {primaryServicePath ? (
                <Link
                  to={primaryServicePath}
                  className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
                >
                  {t(`${root}.hero.secondaryCta`)}
                </Link>
              ) : null}
            </div>

            <div className={`${cardClassName} mx-auto mt-8 max-w-4xl text-left`}>
              <p className="text-base sm:text-lg text-light/85 leading-relaxed">
                {t(`${root}.summary`)}
              </p>

              {heroChips.length > 0 ? (
                <div className="mt-5 flex flex-wrap gap-2">
                  {heroChips.map((chip) => (
                    <span
                      key={chip}
                      className="rounded-full border border-white/15 bg-white/10 px-3 py-1 text-xs sm:text-sm text-light/85"
                    >
                      {chip}
                    </span>
                  ))}
                </div>
              ) : null}
            </div>
          </div>
        </div>
      </section>

      <section className="py-10 sm:py-14">
        <div className="mx-auto grid w-full max-w-6xl gap-4 px-4 sm:px-6 md:grid-cols-2">
          <article className={cardClassName}>
            <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
              {t(`${root}.whenFit.eyebrow`)}
            </p>
            <h2 className="mt-2 text-xl sm:text-2xl font-semibold text-light/90">
              {t(`${root}.whenFit.title`)}
            </h2>
            <ul className="mt-4 list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
              {whenFitItems.map((item, index) => (
                <li key={`${item.item}-${index}`}>{item.item}</li>
              ))}
            </ul>
          </article>

          <article className={cardClassName}>
            <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
              {t(`${root}.commonMistakes.eyebrow`)}
            </p>
            <h2 className="mt-2 text-xl sm:text-2xl font-semibold text-light/90">
              {t(`${root}.commonMistakes.title`)}
            </h2>
            <ul className="mt-4 list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
              {commonMistakesItems.map((item, index) => (
                <li key={`${item.item}-${index}`}>{item.item}</li>
              ))}
            </ul>
          </article>
        </div>
      </section>

      <section className="py-4 sm:py-8">
        <div className="mx-auto w-full max-w-6xl px-4 sm:px-6">
          <article className={`${cardClassName} mx-auto max-w-4xl text-center`}>
            <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
              {t(`${root}.relatedService.eyebrow`)}
            </p>
            <h2 className="mt-2 text-2xl sm:text-3xl poppins-regular text-verde">
              {t(`${root}.relatedService.title`)}
            </h2>
            <p className="mt-4 text-sm sm:text-base text-light/80 leading-relaxed">
              {t(`${root}.relatedService.text`)}
            </p>
            {primaryServicePath ? (
              <div className="mt-6">
                <Link
                  to={primaryServicePath}
                  className="inline-flex rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                >
                  {t(`${root}.relatedService.cta`)}
                </Link>
              </div>
            ) : null}
          </article>
        </div>
      </section>

      <CaseStudyProofGrid
        title={t(`${root}.proof.title`) as string}
        subtitle={t(`${root}.proof.subtitle`) as string}
        labels={proofLabels}
        items={proofItems}
      />

      <section className="py-10 sm:py-14">
        <div className="mx-auto w-full max-w-6xl px-4 sm:px-6">
          <article className={`${cardClassName} mx-auto max-w-4xl`}>
            <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary text-center">
              {t(`${root}.nextStep.eyebrow`)}
            </p>
            <h2 className="mt-2 text-2xl sm:text-3xl poppins-regular text-verde text-center">
              {t(`${root}.nextStep.title`)}
            </h2>
            <p className="mt-4 text-sm sm:text-base text-light/80 text-center leading-relaxed">
              {t(`${root}.nextStep.subtitle`)}
            </p>
            <ul className="mx-auto mt-6 max-w-3xl list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
              {nextStepItems.map((item, index) => (
                <li key={`${item.item}-${index}`}>{item.item}</li>
              ))}
            </ul>
            <div className="mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to={primaryIntentPath}
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t(`${root}.nextStep.primaryCta`)}
              </Link>
              {primaryServicePath ? (
                <Link
                  to={primaryServicePath}
                  className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
                >
                  {t(`${root}.nextStep.secondaryCta`)}
                </Link>
              ) : null}
            </div>
          </article>
        </div>
      </section>
    </Layout>
  );
};

export const ProblemLandingHead: React.FC<Props> = ({ landingKey }) => {
  const { t } = useTranslation(["problem-landings", "index"]);
  const { language, defaultLanguage } = useI18next();
  const config = getProblemLandingConfig(landingKey);
  const root = config.translationRoot;

  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home", { ns: "index" }) as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("menu.servicesHub.nav", { ns: "index" }) as string,
      path: localizeSitePath("/services/", language, defaultLanguage),
    },
    {
      name: t(`${root}.hero.title`) as string,
      path: localizeSitePath(config.path, language, defaultLanguage),
    },
  ]);

  return (
    <SEO
      data={info}
      title={t(`${root}.metaTitle`) as string}
      description={t(`${root}.metaDescription`) as string}
      pathname={config.path}
      schemaType="ProfessionalService"
      pageSchemaType="Service"
      additionalSchemas={breadcrumbSchema ? [breadcrumbSchema] : undefined}
    />
  );
};

export const ProblemLandingHeadProvider: React.FC<
  Props & { data?: LocaleQueryData; pageContext?: I18nPageContext }
> = ({ landingKey, data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <ProblemLandingHead landingKey={landingKey} />
  </I18nHeadProvider>
);
